/* Direct FUN_80099380 grenade callback. */
void thrown_explosive_update(void *raw_object)
{
    SPRITE *object = (SPRITE *)raw_object;
    sint32 old_x = object->collision.x, old_y = object->collision.y, old_z = object->collision.z;
    sint16 type = object->collision.object_type;
    sint32 velocity;
    world_sprite_update(object);
    if ((g_held_buttons & 0x20) == 0)
        object->acceleration_y = 0xa0;
    player_collision_resolve(old_x, old_y, old_z, &object->collision.x, &object->collision.y, &object->collision.z, 0, 0, 0x10, 0x10, 6);
    if (g_collision_flags & 8)
        object->velocity_y = -object->velocity_y;
    if (g_collision_flags & 4)
    {
        velocity = -object->velocity_z;
        object->velocity_z = (velocity < 0 ? velocity + 3 : velocity) >> 2;
    }
    if (g_collision_flags & 2)
    {
        velocity = -object->velocity_x;
        object->velocity_x = (velocity < 0 ? velocity + 3 : velocity) >> 2;
    }
    if ((g_collision_flags & 9) != 0 && type != 0x0b)
    {
        velocity = -object->velocity_y;
        object->velocity_y = (velocity < 0 ? velocity + 3 : velocity) >> 2;
        object->velocity_x = (object->velocity_x + (sint32)((uint32)object->velocity_x >> 31)) >> 1;
        object->velocity_z = (object->velocity_z + (sint32)((uint32)object->velocity_z >> 31)) >> 1;
        if ((object->velocity_y < 0 ? -object->velocity_y : object->velocity_y) > 0x100)
            sound_play_positional(0x18, 0, 0x7f, object->collision.x, object->collision.y, object->collision.z);
    }
    if ((g_collision_flags & 6) != 0 && type != 0x0b && ((object->velocity_x < 0 ? -object->velocity_x : object->velocity_x) > 0x100 || (object->velocity_z < 0 ? -object->velocity_z : object->velocity_z) > 0x100))
        sound_play_positional(0x18, 0, 0x7f, object->collision.x, object->collision.y, object->collision.z);
    if (g_collision_flags != 0 && type == 0x0b)
        sound_play_positional(0x18, 0, 0x7f, object->collision.x, object->collision.y, object->collision.z);
    if (type == 0x86)
    {
        SPRITE *smoke = (SPRITE *)continuous_weapon_particle_create(object->collision.x, object->collision.y - 0x1000, object->collision.z - 0x100, g_signal_flare_sprite_clut);
        if (smoke != 0)
        {
            smoke->field_aa = -3;
            smoke->collision.receives_mask = 4;
            smoke->collision.sends_mask = 0x80;
            smoke->damage = 1;
            smoke->velocity_x *= 2;
            collision_box_set(smoke, 0xe6, 0xe6, 0xe6);
            object->collision.box_y += 0x2000;
        }
    }
    if ((g_collision_flags & 1) != 0 && type == 0x0b)
    {
        SPRITE *effect;
        sint32 surface = g_stage_env->map_resource;
        object_destroy(object);
        if (g_collision_surface_resource == surface || g_collision_surface_resource == -1)
        {
            effect = surface_impact_create(old_x, old_y, old_z, (const sint32 *)player_assets_executable_address(0x800c8d3c));
            g_shared_result_pointer = effect;
            sound_play_positional(0x24, 0, 0x96, old_x, old_y, old_z);
        }
        else
        {
            effect = world_sprite_create(old_x, old_y, old_z, (const sint32 *)player_assets_executable_address(0x800c8b5c));
            g_shared_result_pointer = effect;
            sound_play_positional(9, 0, 0x96, old_x, old_y, old_z);
            expl_flash_create(old_x, old_y - 0x4000, old_z - 0x100);
        }
        effect->cull_distance = 0x3e800;
        effect->field_ae = 1;
        effect->scale_x = (uint16)(random_range(0x800) + 0x2000);
        collision_box_set(effect, 0xa0, 0x60, 0x80);
        effect->collision.receives_mask = 4;
        effect->collision.sends_mask = 1;
        effect->collision.object_type = 2;
        effect->damage = 1;
        effect->collision.box_y += 0x1000;
        player_particle_ring_create(effect->collision.x, effect->collision.y, effect->collision.z, 0x0c, 3);
        camera_shake_start();
    }
}

/* Direct FUN_80099230 constructor. */
SPRITE *thrown_explosive_create(sint32 x, sint32 y, sint32 z, const sint32 *animation)
{
    SPRITE *object = (SPRITE *)runtime_heap_allocate(sizeof(*object));
    POLY_FT4 *prim = (POLY_FT4 *)object->collision.prim;
    sint16 type;
    SetPolyFT4(prim);
    setShadeTex(prim, 0);
    object->collision.update = thrown_explosive_update;
    linked_list_append(g_object_list, object);
    object->cull_distance = 0x3e800;
    object->scale_x = 0x1708;
    animation_start(&object->animation, animation);
    object->collision.x = x;
    object->collision.y = y;
    object->collision.z = z;
    type = g_player->field_240;
    object->collision.object_type = type == 0x89 ? 0x86 : type;
    return object;
}

/* Direct special-projectile callbacks FUN_8009DF84/FUN_8009E118/FUN_800A1C70. */

static sint32 clamp(sint32 value, sint32 minimum, sint32 maximum)
{
    if (value < minimum)
        return minimum;
    if (value > maximum)
        return maximum;
    return value;
}

void homing_projectile_steer(SPRITE *object)
{
    sint32 vx = object->velocity_x;
    sint32 vz = object->velocity_z;
    /* 0x8009DFAC: slt v0, abs(vz), abs(vx).  Steer the weaker
     * horizontal component so homing does not rotate the dominant axis. */
    if ((vz < 0 ? -vz : vz) < (vx < 0 ? -vx : vx))
    {
        if (object->collision.z < object->field_d4)
            vz += 0x40;
        if (object->collision.z > object->field_d4)
            vz -= 0x40;
        object->velocity_z = clamp(vz, -0x400, 0x400);
    }
    else
    {
        if (object->collision.x < object->field_cc)
            vx += 0x40;
        if (object->collision.x > object->field_cc)
            vx -= 0x40;
        object->velocity_x = clamp(vx, -0x400, 0x400);
    }
    if (object->collision.y < object->field_d0)
        object->velocity_y += 0x40;
    if (object->collision.y > object->field_d0)
        object->velocity_y -= 0x40;
    object->velocity_y = clamp(object->velocity_y, -0x200, 0x200);
}

