/* Direct FUN_800A4DC0, using its original 64x64 fixed-angle table at
 * 0x800C3E74. */
sint32 fixed_angle_from_vector(sint32 x, sint32 z)
{
    const sint32 *table = (const sint32 *)player_assets_executable_address(0x800c3e74u);
    sint32 ax = x < 0 ? -x : x;
    sint32 az = z < 0 ? -z : z;
    sint32 angle;
    angle = table[(ax & 0x3f) + ((az & 0x3f) << 6)];
    if (z < 0)
        angle = 0x200 - angle;
    if (x < 0)
        angle = 0x400 - angle;
    return angle;
}
